class DependencyResolver:
    def __init__(self):
        self.requirements = {}

    def add_requirement(self, name, version):
        self.requirements[name] = version

    def parse_and_add(self, line):
        name, version = line.split('==')
        self.add_requirement(name, version)

    def has_conflict(self, name, version):
        return name in self.requirements and self.requirements[name] != version

    def to_requirements_text(self):
        lines = [f'{name}=={version}' for name, version in sorted(self.requirements.items())]
        return '\n'.join(lines)

    def summary(self):
        return {'total': len(self.requirements), 'packages': sorted(self.requirements.keys())}
